import React, { useEffect, useMemo, useState } from 'react';
import { api } from '../../api';
import Cart from '../../components/Cart';
import AddProductModal from '../../components/AddProductModal';
import EditProductModal from '../../components/EditProductModal';
import './ProductsPage.css';

function formatPrice(price) {
    return Number(price).toLocaleString('ru-RU');
}

const imageMap = {
    'M4A1 Patrol': 'm4a1.jpeg',
    'Glock 17 Gen5': 'glock-17.jpeg',
    'Remington 870 Tactical': 'remington-870.jpeg',
    'Taurus .44 Hunter': 'taurus-44.jpeg',
    'SVD Marksman': 'ak-12.jpeg',
    'Beretta 92FS': 'glock-17.jpeg',
    'MP5 SD': 'm4a1.jpeg',
    'Mossberg 590A1': 'remington-870.jpeg',
    'CZ P-10 C': 'taurus-44.jpeg',
    'AK-12': 'ak-12.jpeg'
};

export default function ProductsPage({ userRole }) {
    const [products, setProducts] = useState([]);
    const [loading, setLoading] = useState(true);
    const [showAddModal, setShowAddModal] = useState(false);
    const [editingProduct, setEditingProduct] = useState(null);
    const [cart, setCart] = useState([]);
    const [showCart, setShowCart] = useState(false);

    const [reminderText, setReminderText] = useState('');
    const [reminderTime, setReminderTime] = useState('');
    const [reminders, setReminders] = useState([]);

    const canEdit = userRole === 'seller' || userRole === 'admin';
    const canDelete = userRole === 'admin';
    const isUser = userRole === 'user';

    useEffect(() => {
        loadProducts();
        loadLocalReminders();
    }, []);

    const reminderMin = useMemo(() => new Date().toISOString().slice(0, 16), []);

    const loadProducts = async () => {
        try {
            setLoading(true);
            const data = await api.getProducts();
            setProducts(Array.isArray(data) ? data : []);
        } catch (error) {
            console.error('Error loading products:', error);
            setProducts([]);
        } finally {
            setLoading(false);
        }
    };

    const loadLocalReminders = () => {
        try {
            const raw = localStorage.getItem('arms_reminders');
            const parsed = raw ? JSON.parse(raw) : [];
            setReminders(Array.isArray(parsed) ? parsed : []);
        } catch (error) {
            setReminders([]);
        }
    };

    const persistReminder = (reminder) => {
        const next = [...reminders, reminder];
        setReminders(next);
        localStorage.setItem('arms_reminders', JSON.stringify(next));
    };

    const handleDelete = async (id) => {
        if (!window.confirm('Удалить этот товар?')) return;

        try {
            await api.deleteProduct(id);
            await loadProducts();
        } catch (error) {
            alert('Ошибка при удалении товара');
        }
    };

    const addToCart = (product) => {
        setCart((prev) => {
            const existing = prev.find((item) => item.id === product.id);
            if (existing) {
                return prev.map((item) => (item.id === product.id ? { ...item, quantity: item.quantity + 1 } : item));
            }
            return [...prev, { ...product, quantity: 1 }];
        });
    };

    const getCartQuantity = (productId) => {
        const item = cart.find((entry) => entry.id === productId);
        return item ? item.quantity : 0;
    };

    const handleCheckout = async () => {
        try {
            await api.checkout();
            setCart([]);
            setShowCart(false);
            alert('Заказ успешно оформлен! Спасибо за покупку.');
        } catch (error) {
            alert('Ошибка при оформлении заказа');
        }
    };

    const handleReminderSubmit = async (event) => {
        event.preventDefault();

        const text = reminderText.trim();
        const timestamp = new Date(reminderTime).getTime();

        if (!text || Number.isNaN(timestamp)) {
            alert('Заполните текст и дату напоминания');
            return;
        }

        if (timestamp <= Date.now()) {
            alert('Укажите время в будущем');
            return;
        }

        const reminder = {
            id: Date.now(),
            text,
            reminder: timestamp
        };

        try {
            await api.createReminder({
                id: reminder.id,
                text: reminder.text,
                reminderTime: reminder.reminder
            });
            persistReminder(reminder);
            setReminderText('');
            setReminderTime('');
            alert('Напоминание создано');
        } catch (error) {
            alert('Не удалось создать напоминание');
        }
    };

    if (loading) {
        return (
            <div className="loading">
                <p>Загрузка каталога...</p>
            </div>
        );
    }

    const cartTotalItems = cart.reduce((sum, item) => sum + item.quantity, 0);

    return (
        <div className="products-page">
            <div className="products-toolbar">
                <div className="toolbar-left">
                    {canEdit && (
                        <button className="add-product-btn" onClick={() => setShowAddModal(true)}>
                            Добавить позицию
                        </button>
                    )}
                </div>
                {isUser && (
                    <button className="cart-btn" onClick={() => setShowCart(true)}>
                        Корзина
                        {cartTotalItems > 0 && <span className="cart-badge">{cartTotalItems}</span>}
                    </button>
                )}
            </div>

            <section className="reminder-block">
                <h3>Напоминание</h3>
                <form className="reminder-form" onSubmit={handleReminderSubmit}>
                    <input
                        type="text"
                        placeholder="Текст напоминания"
                        value={reminderText}
                        onChange={(e) => setReminderText(e.target.value)}
                        required
                    />
                    <input
                        type="datetime-local"
                        value={reminderTime}
                        min={reminderMin}
                        onChange={(e) => setReminderTime(e.target.value)}
                        required
                    />
                    <button type="submit" className="add-product-btn">Запланировать</button>
                </form>
                {reminders.length > 0 && (
                    <ul className="reminder-list">
                        {reminders.map((reminder) => (
                            <li key={reminder.id}>
                                <span>{reminder.text}</span>
                                <time>{new Date(reminder.reminder).toLocaleString('ru-RU')}</time>
                            </li>
                        ))}
                    </ul>
                )}
            </section>

            <div className="products-grid">
                {products.map((product) => (
                    <div key={product.id} className="product-card">
                        <img
                            src={`/images/${product.image || imageMap[product.name] || 'glock-17.jpeg'}`}
                            alt={product.name}
                            className="product-image"
                            onError={(event) => {
                                event.target.src = '/images/glock-17.jpeg';
                            }}
                        />
                        <div className="product-content">
                            <h3 className="product-name">{product.name}</h3>
                            <div className="product-category">{product.category}</div>
                            <p className="product-description">{product.description}</p>
                            <div className="product-price">{formatPrice(product.price)} ₽</div>
                            <div className="product-stock">В наличии: {product.stock} шт.</div>
                            <div className="product-actions">
                                {canEdit && (
                                    <button className="action-btn edit-btn" onClick={() => setEditingProduct(product)}>
                                        Изменить
                                    </button>
                                )}
                                {canDelete && (
                                    <button className="action-btn delete-btn" onClick={() => handleDelete(product.id)}>
                                        Удалить
                                    </button>
                                )}
                                {isUser && (
                                    <button className="action-btn cart-add-btn" onClick={() => addToCart(product)}>
                                        {getCartQuantity(product.id) > 0 ? `В корзине: ${getCartQuantity(product.id)}` : 'В корзину'}
                                    </button>
                                )}
                            </div>
                        </div>
                    </div>
                ))}

                {products.length === 0 && (
                    <div className="no-products">
                        <p>Товаров пока нет</p>
                    </div>
                )}
            </div>

            {showAddModal && <AddProductModal onClose={() => setShowAddModal(false)} onSuccess={loadProducts} />}

            {editingProduct && (
                <EditProductModal
                    product={editingProduct}
                    onClose={() => setEditingProduct(null)}
                    onSuccess={loadProducts}
                />
            )}

            {showCart && <Cart items={cart} onClose={() => setShowCart(false)} onCheckout={handleCheckout} />}
        </div>
    );
}
